function Show-Frontmatter([string]$path) {
  Write-Output "----- FILE $path -----"
  $lines = Get-Content -LiteralPath $path
  $in = $false
  $count = 0
  foreach ($line in $lines) {
    if ($line -eq '---') {
      $count++
      if ($count -eq 1) { $in = $true; continue }
      if ($count -eq 2) { break }
    }
    if ($in) { Write-Output $line }
  }
}
