python -c @"
import json
from pathlib import Path
base = Path(r'C:\Users\magicvr\Documents\Code\goal-governance\docs\workspaces\workspace-002-methodology-skills-feedback\GOAL-018-host-wait-and-audit-config\attachments')

def load(name):
    return json.loads((base/name).read_text(encoding='utf-8'))

# remote tag
tag = load('s4-remote-tag.json')
print('=== remote tag keys', list(tag)[:30])
# print compact identity
for k in ['sha','object','tag','name','message','target']:
    if k in tag:
        v = tag[k]
        print(k, json.dumps(v, ensure_ascii=False)[:500])

print('--- nested ---')
def walk(obj, prefix=''):
    if isinstance(obj, dict):
        for k,v in obj.items():
            if k.lower() in {'sha','object','tag','url','type','commit','tagger','message','verification'} or prefix.count('.')<2:
                if not isinstance(v, (dict, list)):
                    print(f'{prefix}{k}={v}')
                elif isinstance(v, dict) and k.lower() in {'object','commit','tagger','verification','target'}:
                    walk(v, prefix+k+'.')
    elif isinstance(obj, list) and obj and prefix=='':
        print('list len', len(obj))
walk(tag)
"@

