python -c @"
import json
from pathlib import Path
base = Path(r'C:\Users\magicvr\Documents\Code\goal-governance\docs\workspaces\workspace-002-methodology-skills-feedback\GOAL-018-host-wait-and-audit-config\attachments')

def summarize(obj, depth=0, maxdepth=3):
    ind='  '*depth
    if isinstance(obj, dict):
        print(f'{ind}dict keys={list(obj.keys())[:40]}')
        if depth < maxdepth:
            for k,v in obj.items():
                if isinstance(v, (dict, list)):
                    print(f'{ind}{k}:')
                    summarize(v, depth+1, maxdepth)
                else:
                    s=str(v)
                    if len(s)>180: s=s[:180]+'...'
                    print(f'{ind}{k}={s}')
    elif isinstance(obj, list):
        print(f'{ind}list len={len(obj)}')
        if obj and depth < maxdepth:
            summarize(obj[0], depth+1, maxdepth)
            if len(obj)>1:
                print(f'{ind}...')
    else:
        print(f'{ind}{obj}')

for name in ['s4-remote-tag.json','s4-release-approvals.json','s4-ghcr-verification.json','s4-ghcr-publish-digest.txt','s4-published-asset-verification.json','s4-formal-install-verification.json','s4-ghcr-invalid-config-verification.json']:
    p=base/name
    print('\n========', name, 'bytes', p.stat().st_size)
    if name.endswith('.txt'):
        print(p.read_text(encoding='utf-8')[:2000])
        continue
    summarize(json.loads(p.read_text(encoding='utf-8')))
"@

